            ('dA', 2 * pi * 10 * .1, 6.28), ('newton9', 4 - 7 / 8, 3.125), ('can r', r, 4.30), ('can h', 500 / (pi * r * r), 8.60), ('can A', 2 * pi * r * r + 1000 / r, 349), ('betz', 4 / 3 * (2 / 3)**2, .593),
            ('fence', 25 * 50, 1250), ('int x2', 8 / 3, 2.667), ('subst', (16 - 1) / 4, 3.75), ('solar', 120 / pi, 38.2), ('rocket', 4.9 * 9, 44.1), ('area', 1 / 2 - 1 / 3, 1 / 6), ('avgval', 9 / 3, 3),
            ('4e', 4 * E_, 10.87), ('tank', .5 / (4 * pi), .0398), ('sqrt int', 16 / 3, 5.33),
            ('labA c', (407.5 - 402.4) / 2, 2.55), ('labA 2nd', 407.5 - 2 * 404.9 + 402.4, .1), ('k1', k1, 1.088953), ('k2', k2, 1.088598), ('kcheck', k2 - .1 * sin(k2), 1.0),
            ('cp.2', 4 * .2 * .64, .512), ('cp.3', 4 * .3 * .49, .588), ('cp.4', 4 * .4 * .36, .576),
